  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_materialCorrelationQualifier)
  }

  /** helper function to set the values of all input ports.
   * @param materialObservation payload for data port materialObservation
   * @param admission payload for data port admission
   */
  def put_concrete_inputs(materialObservation : Factory_Flow.MaterialHandoffObservation,
                          admission : Factory_Flow.AdmissionFact): Unit = {
    put_materialObservation(materialObservation)
    put_admission(admission)
  }


  /** helper function to check MaterialCorrelationQualifier_supervisorProcess_materialCorrelationQualifier's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param materialFact method that will be called with the value of the outgoing data
   *        port 'materialFact'.
   */
  def check_concrete_output(materialFact: Factory_Flow.MaterialFact => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val materialFactValue: Factory_Flow.MaterialFact = get_materialFact().get
    if(!materialFact(materialFactValue)) {
      testFailures = testFailures :+ st"'materialFact' did not match expected: value of the outgoing data port is ${materialFactValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_materialObservation(value : Factory_Flow.MaterialHandoffObservation): Unit = {
    Art.insertInInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_materialCorrelationQualifier.operational_api.materialObservation_Id, Factory_Flow.MaterialHandoffObservation_Payload(value))
