  }

  // getter for out DataPort
  def get_materialFact(): Option[Factory_Flow.MaterialFact] = {
    val value: Option[Factory_Flow.MaterialFact] = get_materialFact_payload() match {
      case Some(Factory_Flow.MaterialFact_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port materialFact.  Expecting 'Factory_Flow.MaterialFact_Payload' but received ${v}")
      case _ => None[Factory_Flow.MaterialFact]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_materialFact_payload(): Option[Factory_Flow.MaterialFact_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.FactoryFlowSupervisor_Instance_supervisorProcess_materialCorrelationQualifier.initialization_api.materialFact_Id).asInstanceOf[Option[Factory_Flow.MaterialFact_Payload]]
